mapper.select:
SELECT V.REQ_DIVISION_CODE AS reqDivisionCode ,V.REQ_ITEM_CODE AS reqItemCode ,V.REQ_BASE_DATE AS reqBaseDate ,ML.ITEM_CODE AS itemCode ,ML.YYYYMM AS matYyyyMm ,ML.INITIAL_QTY AS matInitialQty ,(ML.INPUT_QTY + ML.EXTRA_INPUT_QTY) AS matInputQty ,ML.AGING_PERIOD AS matAgingPeriod ,'BOM' AS matItemType FROM (
SELECT #{r.divisionCode} AS DIVISION_CODE, #{r.itemCode} AS ITEM_CODE, #{r.fromYyyyMm} AS FROM_YYYYMM, #{r.toYyyyMm} AS TO_YYYYMM, #{r.divisionCode} AS REQ_DIVISION_CODE, #{r.itemCode} AS REQ_ITEM_CODE, #{r.baseDate} AS REQ_BASE_DATE
) V JOIN MATERIAL_INV_BAL ML ON ML.ITEM_CODE = V.ITEM_CODE AND ML.DIVISION_CODE = V.DIVISION_CODE AND ML.COMPANY_CODE = #{companyCode} AND ML.YYYYMM = (SELECT MAX(ML2.YYYYMM) FROM MATERIAL_INV_BAL ML2 WHERE ML2.YYYYMM BETWEEN V.FROM_YYYYMM AND V.TO_YYYYMM AND ML2.ITEM_CODE = ML.ITEM_CODE AND ML2.DIVISION_CODE = ML.DIVISION_CODE AND ML2.COMPANY_CODE = ML.COMPANY_CODE AND (ML2.ISSUE_QTY + ML2.EXTRA_ISSUE_QTY) > 0) UNION ALL SELECT DISTINCT V.REQ_DIVISION_CODE AS reqDivisionCode ,V.REQ_ITEM_CODE AS reqItemCode ,V.REQ_BASE_DATE AS reqBaseDate ,ML.ITEM_CODE AS itemCode ,ML.YYYYMM AS matYyyyMm ,ML.INITIAL_QTY AS matInitialQty ,(ML.INPUT_QTY + ML.EXTRA_INPUT_QTY) AS matInputQty ,ML.AGING_PERIOD AS matAgingPeriod ,'FUNGIBLE' AS matItemType FROM (
SELECT #{r.divisionCode} AS DIVISION_CODE, #{r.itemCode} AS ITEM_CODE, #{r.fromYyyyMm} AS FROM_YYYYMM, #{r.toYyyyMm} AS TO_YYYYMM, #{r.divisionCode} AS REQ_DIVISION_CODE, #{r.itemCode} AS REQ_ITEM_CODE, #{r.baseDate} AS REQ_BASE_DATE
) V INNER JOIN FUNGIBLE_MATERIALS FM ON (FM.ITEM_CODE = V.ITEM_CODE OR FM.FUNGIBLE_ITEM_CODE = V.ITEM_CODE) AND FM.DIVISION_CODE = V.DIVISION_CODE AND FM.COMPANY_CODE = #{companyCode} AND FM.DELETE_YN = 'N' INNER JOIN MATERIAL_INV_BAL ML ON ML.ITEM_CODE = CASE WHEN FM.ITEM_CODE = V.ITEM_CODE THEN FM.FUNGIBLE_ITEM_CODE ELSE FM.ITEM_CODE END AND ML.DIVISION_CODE = FM.DIVISION_CODE AND ML.COMPANY_CODE = FM.COMPANY_CODE AND ML.YYYYMM = (SELECT MAX(ML2.YYYYMM) FROM MATERIAL_INV_BAL ML2 WHERE ML2.YYYYMM BETWEEN V.FROM_YYYYMM AND V.TO_YYYYMM AND ML2.ITEM_CODE = ML.ITEM_CODE AND ML2.DIVISION_CODE = ML.DIVISION_CODE AND ML2.COMPANY_CODE = ML.COMPANY_CODE AND (ML2.ISSUE_QTY + ML2.EXTRA_ISSUE_QTY) > 0)

SELECT MAX(ML.YYYYMM)
FROM   MATERIAL_INV_BAL ML
WHERE  ML.YYYYMM <= #{uptoYyyyMm}
AND    ML.ITEM_CODE = #{itemCode}
AND    ML.DIVISION_CODE = #{divisionCode}
AND    ML.COMPANY_CODE = #{companyCode}
AND    ML.INPUT_QTY > 0

SELECT COUNT(*)                          AS poCount
      ,COALESCE(SUM(PL.WAREHOUSING_AMOUNT), 0) AS warehousingAmountSum
FROM   PO_LEDGER PL
WHERE  PL.ITEM_CODE = #{itemCode}
AND    PL.COMPANY_CODE = #{companyCode}
AND    PL.WAREHOUSING_DATE BETWEEN #{fromDate} AND #{toDate}

SELECT V.ITEM_CODE AS itemCode ,V.FROM_DATE AS fromDate ,V.TO_DATE AS toDate ,COUNT(PL.WAREHOUSING_AMOUNT) AS poCount ,COALESCE(SUM(PL.WAREHOUSING_AMOUNT), 0) AS warehousingAmountSum FROM (
SELECT #{r.itemCode} AS ITEM_CODE, #{r.fromDate} AS FROM_DATE, #{r.toDate} AS TO_DATE
) V LEFT OUTER JOIN PO_LEDGER PL ON PL.ITEM_CODE = V.ITEM_CODE AND PL.COMPANY_CODE = #{companyCode} AND PL.WAREHOUSING_DATE BETWEEN V.FROM_DATE AND V.TO_DATE GROUP BY V.ITEM_CODE, V.FROM_DATE, V.TO_DATE

SELECT V.ITEM_CODE AS itemCode ,V.FTA_CODE AS ftaCode ,V.FROM_DATE AS fromDate ,V.TO_DATE AS toDate ,COUNT(CASE WHEN PL.ITEM_CODE IS NOT NULL AND NOT EXISTS (SELECT 1 FROM EXT_COO_CERTIFY_MST ECM INNER JOIN EXT_COO_CERTIFY_DTL ECD ON ECD.COO_CERTIFY_NO = ECM.COO_CERTIFY_NO AND ECD.COMPANY_CODE = ECM.COMPANY_CODE AND ECD.DIVISION_CODE = ECM.DIVISION_CODE AND ECD.VENDOR_CODE = ECM.VENDOR_CODE AND ECD.FTA_CODE = V.FTA_CODE AND ECD.COO_YN = 'Y' WHERE ECM.SUBMIT_STATUS = '4' AND ECM.VENDOR_CODE = PL.VENDOR_CODE AND ECM.COMPANY_CODE = PL.COMPANY_CODE AND ECM.DIVISION_CODE = CASE WHEN ECM.DOCUMENT_TYPE = 'F' THEN PL.DIVISION_CODE WHEN ECM.DOCUMENT_TYPE = 'D' AND ECM.APPLY_TYPE = 'A' THEN ECM.DIVISION_CODE WHEN ECM.DOCUMENT_TYPE = 'D' AND ECM.APPLY_TYPE = 'M' THEN D.COO_RECEIPT_DIVISION_CODE END AND ((ECM.COO_CERTIFY_TYPE = 'C' AND PL.WAREHOUSING_DATE BETWEEN ECD.APPLY_DATE AND ECD.END_DATE) OR (ECM.COO_CERTIFY_TYPE = 'N' AND PL.WAREHOUSING_NO = ECD.WAREHOUSING_NO AND PL.SEQ = ECD.WAREHOUSING_SEQ)) AND ECD.ITEM_CODE = PL.ITEM_CODE) THEN 1 END) AS poCount ,COALESCE(SUM(CASE WHEN PL.ITEM_CODE IS NOT NULL AND NOT EXISTS (SELECT 1 FROM EXT_COO_CERTIFY_MST ECM INNER JOIN EXT_COO_CERTIFY_DTL ECD ON ECD.COO_CERTIFY_NO = ECM.COO_CERTIFY_NO AND ECD.COMPANY_CODE = ECM.COMPANY_CODE AND ECD.DIVISION_CODE = ECM.DIVISION_CODE AND ECD.VENDOR_CODE = ECM.VENDOR_CODE AND ECD.FTA_CODE = V.FTA_CODE AND ECD.COO_YN = 'Y' WHERE ECM.SUBMIT_STATUS = '4' AND ECM.VENDOR_CODE = PL.VENDOR_CODE AND ECM.COMPANY_CODE = PL.COMPANY_CODE AND ECM.DIVISION_CODE = CASE WHEN ECM.DOCUMENT_TYPE = 'F' THEN PL.DIVISION_CODE WHEN ECM.DOCUMENT_TYPE = 'D' AND ECM.APPLY_TYPE = 'A' THEN ECM.DIVISION_CODE WHEN ECM.DOCUMENT_TYPE = 'D' AND ECM.APPLY_TYPE = 'M' THEN D.COO_RECEIPT_DIVISION_CODE END AND ((ECM.COO_CERTIFY_TYPE = 'C' AND PL.WAREHOUSING_DATE BETWEEN ECD.APPLY_DATE AND ECD.END_DATE) OR (ECM.COO_CERTIFY_TYPE = 'N' AND PL.WAREHOUSING_NO = ECD.WAREHOUSING_NO AND PL.SEQ = ECD.WAREHOUSING_SEQ)) AND ECD.ITEM_CODE = PL.ITEM_CODE) THEN PL.WAREHOUSING_AMOUNT END), 0) AS warehousingAmountSum FROM (
SELECT #{r.itemCode} AS ITEM_CODE, #{r.ftaCode} AS FTA_CODE, #{r.fromDate} AS FROM_DATE, #{r.toDate} AS TO_DATE
) V LEFT OUTER JOIN PO_LEDGER PL ON PL.ITEM_CODE = V.ITEM_CODE AND PL.COMPANY_CODE = #{companyCode} AND PL.WAREHOUSING_DATE BETWEEN V.FROM_DATE AND V.TO_DATE LEFT OUTER JOIN COO_DIVISION_V D ON D.DIVISION_CODE = PL.DIVISION_CODE AND D.COMPANY_CODE = PL.COMPANY_CODE GROUP BY V.ITEM_CODE, V.FTA_CODE, V.FROM_DATE, V.TO_DATE
